import type {
  CapabilityExecutionContext,
  CapabilityExecutionEngine,
  CapabilityRegistry,
} from '@handstack/capabilities';
import { ValidationError } from '@handstack/shared';

export interface McpServerPrincipal {
  readonly organizationId: string;
  readonly subject: string;
  readonly permissions: readonly string[];
}

export interface McpServerRequestContext {
  readonly organizationId: string;
  readonly headers?: Readonly<Record<string, string | undefined>>;
  readonly principal?: McpServerPrincipal;
  readonly signal?: AbortSignal;
  readonly requestId?: string;
}

export interface McpResource {
  readonly uri: string;
  readonly name: string;
  readonly description?: string;
  readonly mimeType?: string;
}

export interface McpPrompt {
  readonly name: string;
  readonly description?: string;
  readonly arguments?: readonly { readonly name: string; readonly required?: boolean }[];
}

export interface McpServerAuth {
  authenticate(context: McpServerRequestContext): Promise<McpServerPrincipal | undefined>;
}

export interface McpObservation {
  readonly method: string;
  readonly outcome: 'success' | 'error';
  readonly durationMs: number;
}

export type McpObservationSink = (observation: McpObservation) => void;

export interface McpJsonRpcRequest {
  readonly jsonrpc: '2.0';
  readonly id?: string | number | null;
  readonly method: string;
  readonly params?: Record<string, unknown>;
}

export interface McpJsonRpcResponse {
  readonly jsonrpc: '2.0';
  readonly id: string | number | null;
  readonly result?: unknown;
  readonly error?: { readonly code: number; readonly message: string };
}

const invalidRequest = -32600;
const methodNotFound = -32601;
const invalidParams = -32602;
const unauthorized = -32001;

export class McpServer {
  constructor(
    private readonly registry: CapabilityRegistry,
    private readonly engine: CapabilityExecutionEngine,
    private readonly auth?: McpServerAuth,
    private readonly resources: readonly McpResource[] = [],
    private readonly prompts: readonly McpPrompt[] = [],
    private readonly observe?: McpObservationSink,
  ) {}

  async handle(
    request: unknown,
    context: McpServerRequestContext,
  ): Promise<McpJsonRpcResponse | undefined> {
    const started = performance.now();
    let outcome: McpObservation['outcome'] = 'success';
    if (!isRequest(request))
      return response(null, undefined, {
        code: invalidRequest,
        message: 'Invalid JSON-RPC request',
      });
    const id = request.id === undefined ? null : request.id;
    try {
      const principal = await this.authenticate(context);
      if (request.method === 'notifications/initialized') return undefined;
      if (request.method === 'initialize') {
        return response(id, {
          protocolVersion: '2025-06-18',
          capabilities: { tools: {}, resources: {}, prompts: {} },
          serverInfo: { name: 'handstack-mcp', version: '0.0.0' },
        });
      }
      if (principal === undefined) {
        outcome = 'error';
        return response(id, undefined, {
          code: unauthorized,
          message: 'MCP authentication required',
        });
      }
      switch (request.method) {
        case 'tools/list':
          return response(id, { tools: await this.tools(principal.organizationId) });
        case 'resources/list':
          return response(id, { resources: this.resources });
        case 'prompts/list':
          return response(id, { prompts: this.prompts });
        case 'tools/call':
          return response(id, await this.call(request.params, context, principal));
        default:
          outcome = 'error';
          return response(id, undefined, { code: methodNotFound, message: 'MCP method not found' });
      }
    } catch (error) {
      outcome = 'error';
      const message = error instanceof ValidationError ? error.message : 'MCP request failed';
      return response(id, undefined, { code: invalidParams, message });
    } finally {
      if (isRequest(request))
        this.observe?.({
          method: request.method,
          outcome,
          durationMs: Math.max(0, performance.now() - started),
        });
    }
  }

  private async authenticate(
    context: McpServerRequestContext,
  ): Promise<McpServerPrincipal | undefined> {
    if (context.principal !== undefined) {
      if (context.principal.organizationId !== context.organizationId)
        throw new ValidationError('MCP organization mismatch');
      return context.principal;
    }
    return this.auth?.authenticate(context);
  }

  private async tools(organizationId: string) {
    return (await this.registry.list(organizationId, 'MCP')).map((capability) => ({
      name: capability.slug,
      description: capability.description,
      inputSchema: capability.inputSchema,
    }));
  }

  private async call(
    params: Record<string, unknown> | undefined,
    context: McpServerRequestContext,
    principal: McpServerPrincipal,
  ) {
    if (params === undefined || typeof params.name !== 'string')
      throw new ValidationError('MCP tool name is required');
    const input = params.arguments;
    const executionContext: CapabilityExecutionContext = {
      organizationId: context.organizationId,
      principalId: principal.subject,
      channel: 'MCP',
      permissions: principal.permissions,
      ...(context.signal === undefined ? {} : { signal: context.signal }),
      ...(context.requestId === undefined ? {} : { requestId: context.requestId }),
    };
    const result = await this.engine.execute(params.name, input, executionContext);
    return { content: [{ type: 'text', text: JSON.stringify(result) }] };
  }
}

function isRequest(value: unknown): value is McpJsonRpcRequest {
  if (typeof value !== 'object' || value === null) return false;
  const record = value as Record<string, unknown>;
  return record.jsonrpc === '2.0' && typeof record.method === 'string';
}

function response(
  id: string | number | null,
  result?: unknown,
  error?: { readonly code: number; readonly message: string },
): McpJsonRpcResponse {
  return {
    jsonrpc: '2.0',
    id,
    ...(result === undefined ? {} : { result }),
    ...(error === undefined ? {} : { error }),
  };
}
import { CapabilityExecutionEngine, InMemoryCapabilityRegistry } from '@handstack/capabilities';
import { describe, expect, it } from 'vitest';
import { McpServer } from '../src/index.js';

describe('MCP server', () => {
  it('emits method outcome and duration without request payloads', async () => {
    const observations: { method: string; outcome: string; durationMs: number }[] = [];
    const server = new McpServer(
      new InMemoryCapabilityRegistry(),
      new CapabilityExecutionEngine(new InMemoryCapabilityRegistry(), {
        authorize: () => Promise.resolve(),
      }),
      undefined,
      [],
      [],
      (observation) => observations.push(observation),
    );
    await server.handle({ jsonrpc: '2.0', id: 1, method: 'tools/list' }, { organizationId: 'org' });
    expect(observations).toMatchObject([{ method: 'tools/list', outcome: 'error' }]);
    expect(Number.isFinite(observations[0]?.durationMs)).toBe(true);
  });

  it('lists and executes only published MCP capabilities for the principal tenant', async () => {
    const registry = new InMemoryCapabilityRegistry();
    await registry.register({
      organizationId: 'org',
      slug: 'echo',
      name: 'Echo',
      description: 'Echo input',
      type: 'TOOL',
      inputSchema: { type: 'object' },
      outputSchema: {},
      requiredPermissions: ['mcp.echo'],
      allowedChannels: ['MCP'],
      timeoutMs: 1000,
      visibility: 'ORGANIZATION',
      ownerId: 'owner',
      metadata: {},
      handler: (input) => Promise.resolve(input),
    });
    const engine = new CapabilityExecutionEngine(registry, {
      authorize: ({ capability, context }) =>
        capability.requiredPermissions.every((permission) =>
          context.permissions?.includes(permission),
        )
          ? Promise.resolve()
          : Promise.reject(new Error('permission denied')),
    });
    const server = new McpServer(registry, engine);
    await expect(
      server.handle(
        { jsonrpc: '2.0', id: 1, method: 'tools/list' },
        {
          organizationId: 'org',
          principal: { organizationId: 'org', subject: 'user', permissions: ['mcp.echo'] },
        },
      ),
    ).resolves.toMatchObject({ result: { tools: [{ name: 'echo' }] } });
    await expect(
      server.handle(
        {
          jsonrpc: '2.0',
          id: 2,
          method: 'tools/call',
          params: { name: 'echo', arguments: { ok: true } },
        },
        {
          organizationId: 'org',
          principal: { organizationId: 'org', subject: 'user', permissions: ['mcp.echo'] },
        },
      ),
    ).resolves.toMatchObject({ result: { content: [{ text: '{"ok":true}' }] } });
    await expect(
      server.handle(
        { jsonrpc: '2.0', id: 3, method: 'tools/call', params: { name: 'echo', arguments: {} } },
        {
          organizationId: 'other',
          principal: { organizationId: 'other', subject: 'user', permissions: ['mcp.echo'] },
        },
      ),
    ).resolves.toMatchObject({ error: { code: -32602 } });
  });

  it('requires authentication before discovery and supports resources/prompts', async () => {
    const registry = new InMemoryCapabilityRegistry();
    const engine = new CapabilityExecutionEngine(registry, { authorize: () => Promise.resolve() });
    const server = new McpServer(
      registry,
      engine,
      undefined,
      [{ uri: 'file://a', name: 'a' }],
      [{ name: 'summarize' }],
    );
    await expect(
      server.handle({ jsonrpc: '2.0', id: 1, method: 'tools/list' }, { organizationId: 'org' }),
    ).resolves.toMatchObject({ error: { code: -32001 } });
    await expect(
      server.handle(
        { jsonrpc: '2.0', id: 2, method: 'resources/list' },
        {
          organizationId: 'org',
          principal: { organizationId: 'org', subject: 'u', permissions: [] },
        },
      ),
    ).resolves.toMatchObject({ result: { resources: [{ name: 'a' }] } });
    await expect(
      server.handle(
        { jsonrpc: '2.0', id: 3, method: 'prompts/list' },
        {
          organizationId: 'org',
          principal: { organizationId: 'org', subject: 'u', permissions: [] },
        },
      ),
    ).resolves.toMatchObject({ result: { prompts: [{ name: 'summarize' }] } });
  });
});

import { ValidationError } from '@handstack/shared';
import type { CapabilityRegistry } from '@handstack/capabilities';
import { spawn, type ChildProcessWithoutNullStreams } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { once } from 'node:events';

export type McpTransportKind = 'STREAMABLE_HTTP' | 'STDIO';
export type McpAuthType = 'NONE' | 'API_KEY' | 'BEARER' | 'OAUTH2' | 'OIDC' | 'CUSTOM_HEADERS';

export interface McpCredential {
  readonly type: McpAuthType;
  readonly secret?: string;
  readonly headers?: Readonly<Record<string, string>>;
}

export interface McpServerConfig {
  readonly id: string;
  readonly organizationId: string;
  readonly name: string;
  readonly transport: McpTransportKind;
  readonly url?: string;
  readonly endpoint?: string;
  readonly command?: string;
  readonly args?: readonly string[];
  readonly environment?: Readonly<Record<string, string>>;
  readonly auth?: McpCredential;
  readonly credentialResolver?: (context: McpCallContext) => Promise<McpCredential | undefined>;
  readonly allowedPermissions: readonly string[];
}

export interface McpTool {
  readonly name: string;
  readonly description?: string;
  readonly inputSchema: Record<string, unknown>;
  readonly requiredPermissions: readonly string[];
}

export interface McpResource {
  readonly uri: string;
  readonly name: string;
  readonly description?: string;
  readonly mimeType?: string;
}

export interface McpPrompt {
  readonly name: string;
  readonly description?: string;
  readonly arguments?: readonly { readonly name: string; readonly required?: boolean }[];
}

export interface McpCallContext {
  readonly organizationId: string;
  readonly principalId: string;
  readonly permissions: readonly string[];
  readonly credential?: McpCredential;
  readonly signal?: AbortSignal;
}

export interface McpObservation {
  readonly operation: 'discover' | 'call';
  readonly method: string;
  readonly outcome: 'success' | 'error';
  readonly durationMs: number;
}

export type McpObservationSink = (observation: McpObservation) => void;

export interface McpTransport {
  request(
    method: string,
    params: Record<string, unknown>,
    signal?: AbortSignal,
    credential?: McpCredential | (() => Promise<McpCredential | undefined>),
  ): Promise<unknown>;
  close(): Promise<void>;
}

class StreamableHttpTransport implements McpTransport {
  constructor(private readonly config: McpServerConfig) {}

  async request(
    method: string,
    params: Record<string, unknown>,
    signal?: AbortSignal,
    credential?: McpCredential,
  ) {
    const endpoint = this.config.endpoint ?? this.config.url;
    if (endpoint === undefined || endpoint === '')
      throw new ValidationError('MCP HTTP URL is required');
    const headers: Record<string, string> = {
      'content-type': 'application/json',
      accept: 'application/json, text/event-stream',
    };
    const configuredAuth = credential ?? this.config.auth;
    if (
      configuredAuth?.type === 'BEARER' ||
      configuredAuth?.type === 'OAUTH2' ||
      configuredAuth?.type === 'OIDC'
    ) {
      if (configuredAuth.secret !== undefined)
        headers.authorization = `Bearer ${configuredAuth.secret}`;
    } else if (configuredAuth?.type === 'API_KEY' && configuredAuth.secret !== undefined) {
      headers.authorization = `Api-Key ${configuredAuth.secret}`;
    } else if (configuredAuth?.type === 'CUSTOM_HEADERS' && configuredAuth.headers !== undefined) {
      Object.assign(headers, configuredAuth.headers);
    }
    const requestInit: RequestInit = {
      method: 'POST',
      headers,
      body: JSON.stringify({ jsonrpc: '2.0', id: randomUUID(), method, params }),
      ...(signal === undefined ? {} : { signal }),
    };
    const response = await fetch(endpoint, requestInit);
    if (!response.ok) throw new Error(`MCP server returned HTTP ${String(response.status)}`);
    const value = (await response.json()) as unknown;
    if (!isRecord(value) || ('error' in value && value.error !== undefined))
      throw new Error('MCP server returned a JSON-RPC error');
    return value.result;
  }

  close() {
    return Promise.resolve();
  }
}

class StdioTransport implements McpTransport {
  private readonly process: ChildProcessWithoutNullStreams;
  private readonly pending = new Map<
    string,
    { resolve: (value: unknown) => void; reject: (error: Error) => void }
  >();
  private buffer = '';

  constructor(config: McpServerConfig) {
    if (config.command === undefined || config.command === '')
      throw new ValidationError('MCP stdio command is required');
    this.process = spawn(config.command, [...(config.args ?? [])], {
      stdio: 'pipe',
      windowsHide: true,
    });
    this.process.stdout.on('data', (chunk: Buffer) => {
      this.consume(chunk.toString('utf8'));
    });
    this.process.on('error', (error) => {
      this.pending.forEach(({ reject }) => {
        reject(error);
      });
    });
  }

  request(method: string, params: Record<string, unknown>, signal?: AbortSignal) {
    const id = randomUUID();
    return new Promise<unknown>((resolve, reject) => {
      const abort = () => {
        this.pending.delete(id);
        reject(new Error('MCP request aborted'));
      };
      signal?.addEventListener('abort', abort, { once: true });
      this.pending.set(id, {
        resolve: (value) => {
          signal?.removeEventListener('abort', abort);
          resolve(value);
        },
        reject: (error) => {
          signal?.removeEventListener('abort', abort);
          reject(error);
        },
      });
      this.process.stdin.write(`${JSON.stringify({ jsonrpc: '2.0', id, method, params })}\n`);
    });
  }

  private consume(chunk: string) {
    this.buffer += chunk;
    while (this.buffer.includes('\n')) {
      const index = this.buffer.indexOf('\n');
      const line = this.buffer.slice(0, index).trim();
      this.buffer = this.buffer.slice(index + 1);
      if (line === '') continue;
      let value: unknown;
      try {
        value = JSON.parse(line) as unknown;
      } catch {
        continue;
      }
      if (!isRecord(value) || typeof value.id !== 'string') continue;
      const pending = this.pending.get(value.id);
      if (pending === undefined) continue;
      this.pending.delete(value.id);
      if ('error' in value && value.error !== undefined)
        pending.reject(new Error('MCP JSON-RPC error'));
      else pending.resolve(value.result);
    }
  }

  async close() {
    if (this.process.exitCode === null) {
      this.process.kill();
      await once(this.process, 'close').catch(() => {
        return undefined;
      });
    }
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

export class McpClientRegistry {
  private readonly servers = new Map<string, McpServerConfig>();
  private readonly transports = new Map<string, McpTransport>();
  private readonly tools = new Map<string, readonly McpTool[]>();
  private readonly resources = new Map<string, readonly McpResource[]>();
  private readonly prompts = new Map<string, readonly McpPrompt[]>();

  constructor(private readonly observe?: McpObservationSink) {}

  register(server: McpServerConfig): void {
    if (server.organizationId === '' || server.id === '')
      throw new ValidationError('MCP server organization and id are required');
    if (this.servers.has(`${server.organizationId}:${server.id}`))
      throw new ValidationError('MCP server already exists');
    this.servers.set(`${server.organizationId}:${server.id}`, server);
  }

  async discover(
    organizationId: string,
    serverId: string,
    signal?: AbortSignal,
  ): Promise<readonly McpTool[]> {
    const server = this.require(organizationId, serverId);
    const result = await this.observedRequest('discover', 'tools/list', server, signal);
    if (!isRecord(result) || !Array.isArray(result.tools))
      throw new Error('MCP tools/list returned an invalid response');
    const discovered = result.tools.filter(isRecord).map((tool) => ({
      name: String(tool.name),
      ...(typeof tool.description === 'string' ? { description: tool.description } : {}),
      inputSchema: isRecord(tool.inputSchema) ? tool.inputSchema : {},
      requiredPermissions: Array.isArray(tool.requiredPermissions)
        ? tool.requiredPermissions.filter(
            (permission): permission is string => typeof permission === 'string',
          )
        : [],
    }));
    this.tools.set(`${organizationId}:${serverId}`, discovered);
    return discovered;
  }

  listTools(organizationId: string, serverId: string): readonly McpTool[] {
    return this.tools.get(`${organizationId}:${serverId}`) ?? [];
  }

  async discoverResources(
    organizationId: string,
    serverId: string,
    signal?: AbortSignal,
  ): Promise<readonly McpResource[]> {
    const result = await this.observedRequest(
      'discover',
      'resources/list',
      this.require(organizationId, serverId),
      signal,
    );
    if (!isRecord(result) || !Array.isArray(result.resources))
      throw new Error('MCP resources/list returned an invalid response');
    const discovered = result.resources.filter(isRecord).map((resource) => ({
      uri: String(resource.uri),
      name: String(resource.name),
      ...(typeof resource.description === 'string' ? { description: resource.description } : {}),
      ...(typeof resource.mimeType === 'string' ? { mimeType: resource.mimeType } : {}),
    }));
    this.resources.set(`${organizationId}:${serverId}`, discovered);
    return discovered;
  }

  listResources(organizationId: string, serverId: string): readonly McpResource[] {
    return this.resources.get(`${organizationId}:${serverId}`) ?? [];
  }

  async discoverPrompts(
    organizationId: string,
    serverId: string,
    signal?: AbortSignal,
  ): Promise<readonly McpPrompt[]> {
    const result = await this.observedRequest(
      'discover',
      'prompts/list',
      this.require(organizationId, serverId),
      signal,
    );
    if (!isRecord(result) || !Array.isArray(result.prompts))
      throw new Error('MCP prompts/list returned an invalid response');
    const discovered = result.prompts.filter(isRecord).map((prompt) => ({
      name: String(prompt.name),
      ...(typeof prompt.description === 'string' ? { description: prompt.description } : {}),
      ...(Array.isArray(prompt.arguments)
        ? {
            arguments: prompt.arguments.filter(isRecord).map((argument) => ({
              name: String(argument.name),
              ...(typeof argument.required === 'boolean' ? { required: argument.required } : {}),
            })),
          }
        : {}),
    }));
    this.prompts.set(`${organizationId}:${serverId}`, discovered);
    return discovered;
  }

  listPrompts(organizationId: string, serverId: string): readonly McpPrompt[] {
    return this.prompts.get(`${organizationId}:${serverId}`) ?? [];
  }

  /** Exposes discovered MCP tools as AGENT capabilities for AgentHarness. */
  async registerCapabilities(
    registry: CapabilityRegistry,
    organizationId: string,
    serverId: string,
    ownerId: string,
  ): Promise<readonly string[]> {
    const server = this.require(organizationId, serverId);
    const tools = this.listTools(organizationId, serverId);
    if (tools.length === 0) throw new ValidationError('MCP tools must be discovered first');
    const registered: string[] = [];
    for (const tool of tools) {
      await registry.register({
        organizationId,
        slug: tool.name,
        name: tool.name,
        description: tool.description ?? `MCP tool from ${server.name}`,
        type: 'TOOL',
        inputSchema: tool.inputSchema,
        outputSchema: {},
        requiredPermissions: [...tool.requiredPermissions, ...server.allowedPermissions],
        allowedChannels: ['AGENT'],
        timeoutMs: 30_000,
        visibility: 'ORGANIZATION',
        ownerId,
        metadata: { mcpServerId: serverId, mcpTool: tool.name },
        handler: (input, context) => {
          const callContext: McpCallContext = {
            organizationId: context.organizationId,
            principalId: context.principalId,
            permissions: context.permissions ?? [],
            ...(context.signal === undefined ? {} : { signal: context.signal }),
          };
          return this.execute(organizationId, serverId, tool.name, input, callContext);
        },
      });
      registered.push(tool.name);
    }
    return registered;
  }

  async execute(
    organizationId: string,
    serverId: string,
    toolName: string,
    argumentsValue: unknown,
    context: McpCallContext,
  ): Promise<unknown> {
    const server = this.require(organizationId, serverId);
    if (context.organizationId !== organizationId)
      throw new ValidationError('MCP organization mismatch');
    const tool = this.listTools(organizationId, serverId).find(
      (candidate) => candidate.name === toolName,
    );
    if (tool === undefined) throw new ValidationError('MCP tool has not been discovered');
    const missing = [...server.allowedPermissions, ...tool.requiredPermissions].filter(
      (permission) => !context.permissions.includes(permission),
    );
    if (missing.length > 0) throw new ValidationError('MCP tool permission denied');
    const credential =
      server.credentialResolver === undefined
        ? context.credential
        : await server.credentialResolver(context);
    return this.observedRequest('call', 'tools/call', server, context.signal, credential, {
      name: toolName,
      arguments: argumentsValue,
    });
  }

  async close(organizationId: string, serverId: string): Promise<void> {
    const key = `${organizationId}:${serverId}`;
    const transport = this.transports.get(key);
    if (transport !== undefined) {
      await transport.close();
      this.transports.delete(key);
    }
  }

  private require(organizationId: string, serverId: string) {
    const server = this.servers.get(`${organizationId}:${serverId}`);
    if (server === undefined) throw new ValidationError('MCP server not found');
    return server;
  }

  private async observedRequest(
    operation: McpObservation['operation'],
    method: string,
    server: McpServerConfig,
    signal?: AbortSignal,
    credential?: McpCredential,
    params: Record<string, unknown> = {},
  ): Promise<unknown> {
    const started = performance.now();
    try {
      const resolvedCredential =
        typeof credential === 'function' ? await credential() : credential;
      const result = await this.transport(server).request(
        method,
        params,
        signal,
        resolvedCredential,
      );
      this.observe?.({ operation, method, outcome: 'success', durationMs: elapsed(started) });
      return result;
    } catch (error) {
      this.observe?.({ operation, method, outcome: 'error', durationMs: elapsed(started) });
      throw error;
    }
  }
  private transport(server: McpServerConfig) {
    const key = `${server.organizationId}:${server.id}`;
    const existing = this.transports.get(key);
    if (existing !== undefined) return existing;
    const transport =
      server.transport === 'STREAMABLE_HTTP'
        ? new StreamableHttpTransport(server)
        : new StdioTransport(server);
    this.transports.set(key, transport);
    return transport;
  }
}

function elapsed(started: number): number {
  return Math.max(0, performance.now() - started);
}
import { describe, expect, it, vi } from 'vitest';
import { CapabilityExecutionEngine, InMemoryCapabilityRegistry } from '@handstack/capabilities';
import { McpClientRegistry } from '../src/index.js';

describe('MCP client registry', () => {
  it('emits safe observations for discovery, calls and failures', async () => {
    const observations: {
      operation: string;
      method: string;
      outcome: string;
      durationMs: number;
    }[] = [];
    const fetchMock = vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      json: () => Promise.resolve({ result: { tools: [{ name: 'ping', inputSchema: {} }] } }),
    });
    vi.stubGlobal('fetch', fetchMock);
    const registry = new McpClientRegistry((observation) => observations.push(observation));
    registry.register({
      id: 'observed',
      organizationId: 'org',
      name: 'Observed',
      transport: 'STREAMABLE_HTTP',
