398:  private async observedRequest(
399:    operation: McpObservation['operation'],
400:    method: string,
401:    server: McpServerConfig,
402:    signal?: AbortSignal,
403:    credential?: McpCredential,
404:    params: Record<string, unknown> = {},
405:  ): Promise<unknown> {
406:    const started = performance.now();
407:    try {
408:      const resolvedCredential =
