314:export class RepositoryJobTransport<T> implements DurableJobTransport<T>, JobDeadLetterAdmin<T> {
315:  private readonly repository: Repository<JobEntity>;
316:  private lock: Promise<void> = Promise.resolve();
317:
318:  constructor(
319:    repositoryFactory: <E extends TenantEntity>(name: RepositoryName) => Repository<E>,
320:    private readonly organizationId: string,
321:    private readonly leaseMs = 60_000,
322:  ) {
323:    if (organizationId === '') throw new ValidationError('Job organization is required');
324:    if (leaseMs < 1) throw new ValidationError('Job lease must be positive');
325:    this.repository = repositoryFactory<JobEntity>(repositoryName('jobs'));
326:  }
327:
328:  enqueue(queue: JobQueueName, job: Job<T>): Promise<void> {
329:    return this.serial(async () => {
330:      const existing = await this.findQueue(
331:        queue,
332:        (item) => item.job.idempotencyKey === job.idempotencyKey && item.state !== 'DEAD',
333:      );
334:      if (existing !== undefined) return;
335:      const now = new Date();
336:      await this.repository.insert({
337:        id: `${queue}:${job.id}`,
338:        tenantId: this.organizationId,
339:        version: 1,
340:        createdAt: now,
341:        updatedAt: now,
342:        queueName: queue,
343:        state: 'PENDING',
344:        job,
345:      });
346:    });
347:  }
348:
349:  dequeue(queue: JobQueueName): Promise<Job<T> | undefined> {
350:    return this.serial(async () => {
351:      const now = Date.now();
352:      const candidate = await this.findQueue(
353:        queue,
354:        (item) =>
355:          (item.state === 'PENDING' && item.job.availableAt <= now) ||
356:          (item.state === 'CLAIMED' && (item.leaseUntil ?? 0) <= now),
357:      );
358:      if (candidate === undefined) return undefined;
359:      const claimed: JobEntity = {
360:        ...candidate,
361:        version: candidate.version + 1,
362:        updatedAt: new Date(),
363:        state: 'CLAIMED',
364:        leaseUntil: now + this.leaseMs,
365:      };
366:      await this.repository.update(claimed, candidate.version);
367:      return claimed.job as Job<T>;
368:    });
369:  }
370:
371:  requeue(queue: JobQueueName, job: Job<T>, delayMs: number): Promise<void> {
372:    return this.serial(() =>
373:      this.updateState(queue, job.id, 'PENDING', { ...job, availableAt: Date.now() + delayMs }),
374:    );
375:  }
