377:  deadLetter(queue: JobQueueName, job: Job<T>, error: unknown): Promise<void> {
378:    return this.serial(() =>
379:      this.updateState(
380:        queue,
381:        job.id,
382:        'DEAD',
383:        job,
384:        error instanceof Error ? error.message : String(error),
385:      ),
386:    );
387:  }
