394:  async listDeadLetters(queue: JobQueueName): Promise<readonly DeadLetterJob<T>[]> {
395:    return (await this.listQueue(queue))
396:      .filter((item) => item.state === 'DEAD')
397:      .map((item) => ({
398:        job: item.job as Job<T>,
399:        error: item.error ?? 'Unknown job failure',
400:        deadLetteredAt: item.updatedAt,
401:      }));
402:  }
403:
404:  async retryDeadLetter(queue: JobQueueName, idempotencyKey: string): Promise<Job<T> | undefined> {
405:    return this.serial(async () => {
406:      const item = (await this.listQueue(queue)).find(
407:        (candidate) =>
408:          candidate.state === 'DEAD' && candidate.job.idempotencyKey === idempotencyKey,
409:      );
410:      if (item === undefined) return undefined;
411:      const job = { ...item.job, attempts: 0, availableAt: Date.now() } as Job<T>;
412:      const withoutError = { ...item };
413:      delete withoutError.error;
414:      await this.repository.update(
415:        {
416:          ...withoutError,
417:          version: item.version + 1,
418:          updatedAt: new Date(),
419:          state: 'PENDING',
420:          job,
421:        },
422:        item.version,
423:      );
