429:    return this.serial(async () => {
430:      const item = (await this.listQueue(queue)).find(
431:        (candidate) =>
432:          candidate.state === 'DEAD' && candidate.job.idempotencyKey === idempotencyKey,
433:      );
434:      return item === undefined
435:        ? false
436:        : this.repository.delete(this.organizationId, item.id, item.version);
437:    });
438:  }
