440:  private async updateState(
441:    queue: JobQueueName,
442:    id: string,
443:    state: JobState,
444:    job: Job<T>,
445:    error?: string,
446:  ): Promise<void> {
447:    const current = await this.repository.findById(this.organizationId, `${queue}:${id}`);
448:    if (current === undefined) return;
449:    await this.repository.update(
450:      {
451:        ...current,
452:        version: current.version + 1,
453:        updatedAt: new Date(),
454:        state,
455:        job,
456:        ...(error === undefined ? {} : { error }),
457:        ...(state === 'PENDING' ? { leaseUntil: 0 } : {}),
458:      },
459:      current.version,
460:    );
461:  }
462:
463:  private async listQueue(queue: JobQueueName): Promise<readonly JobEntity[]> {
464:    const values: JobEntity[] = [];
465:    let cursor: string | undefined;
466:    do {
467:      const page = await this.repository.list(this.organizationId, {
468:        limit: 200,
469:        ...(cursor === undefined ? {} : { cursor }),
470:      });
471:      values.push(...page.items.filter((item) => item.queueName === queue));
472:      cursor = page.nextCursor;
473:    } while (cursor !== undefined);
474:    return values;
475:  }
476:
477:  private async findQueue(
478:    queue: JobQueueName,
479:    predicate: (item: JobEntity) => boolean,
480:  ): Promise<JobEntity | undefined> {
481:    return (await this.listQueue(queue))
482:      .filter(predicate)
483:      .sort(
484:        (left, right) =>
485:          right.job.priority - left.job.priority ||
486:          left.job.createdAt.getTime() - right.job.createdAt.getTime(),
487:      )[0];
488:  }
