490:  private serial<R>(operation: () => Promise<R>): Promise<R> {
491:    const next = this.lock.then(operation, operation);
492:    this.lock = next.then(
493:      () => undefined,
494:      () => undefined,
495:    );
496:    return next;
497:  }
498:}
