1016:async function withTimeout<T>(
1017:  operation: Promise<T>,
1018:  ms: number,
1019:  controller: AbortController,
1020:): Promise<T> {
1021:  let timer: ReturnType<typeof setTimeout> | undefined;
1022:  const timeoutPromise = new Promise<never>((_, reject) => {
1023:    timer = setTimeout(() => {
1024:      controller.abort();
1025:      reject(new Error('Job timeout'));
1026:    }, ms);
1027:  });
1028:  try {
1029:    return await Promise.race([operation, timeoutPromise]);
1030:  } finally {
1031:    if (timer !== undefined) clearTimeout(timer);
1032:  }
1033:}
